 target='/home/ubuntu/.cache/huggingface/hub/models--Qwen--Qwen3-8B/snapshots/b968826d9c46dd6066d109eabc6255188de91218'
 tokenizer=AutoTokenizer.from_pretrained(target,local_files_only=True)
